def countSignAssignments(nums, target):
    total = sum(nums)
    if abs(target) > total or (total + target) % 2:
        return 0
    need = (total + target) // 2
    ways = [0] * (need + 1)
    ways[0] = 1
    for x in nums:
        for s in range(need, x - 1, -1):
            ways[s] += ways[s - x]
    return ways[need]
